<?php
namespace App\Http\Controllers;
use App\Models\DiningSession; use App\Models\OrderItem; use Illuminate\Http\Request;
class OrderItemController extends Controller { public function cancel(Request $r,int $id){$d=$r->validate(['reason'=>'required|string|max:500']);$i=OrderItem::whereHas('order',fn($q)=>$q->where('restaurant_id',$r->user()->restaurant_id))->findOrFail($id);$i->update(['status'=>'Cancelled','cancel_reason'=>$d['reason']]);return response()->json(['data'=>$i]);} public function reassign(Request $r,int $id){$d=$r->validate(['target_session_id'=>'required|integer']);$i=OrderItem::whereHas('order',fn($q)=>$q->where('restaurant_id',$r->user()->restaurant_id))->findOrFail($id);$s=DiningSession::where('restaurant_id',$r->user()->restaurant_id)->whereKey($d['target_session_id'])->where('status','!=','Closed')->firstOrFail();$i->update(['reassigned_to_session_id'=>$s->id,'status'=>'Reassigned']);return response()->json(['data'=>$i->load('reassignedSession')]);}}
